use gpui_mesh::{Association,DataSet,Field,FieldData,TimeSeries};
use gpui_profiler::AllocProbe;
use gpui_scene3d::Player;
use std::{hint::black_box,time::Instant};

fn fixture(n:usize,mode:&str,simple:bool)->TimeSeries {
    let dataset=DataSet::structured_grid("time",[n;3],[0.0;3],[0.5;3]).unwrap();
    let points=dataset.point_count();let cells=dataset.cell_count();
    let mut a=dataset.with_field(Field::scalar("p",vec![1.25;points])).with_field(Field::vector("v",vec![[1.25;3];points]));
    if !simple {
        a=a.with_field(Field::tensor("t",vec![[1.25;6];points])).with_field(Field::complex("c",vec![[1.25;2];points]));
        for shape in [1,3,6,2] {
            a=a.with_field(match shape {1=>Field::scalar("s",vec![1.25;cells]).on_cells(),3=>Field::vector("v",vec![[1.25;3];cells]).on_cells(),6=>Field::tensor("t",vec![[1.25;6];cells]).on_cells(),_=>Field::complex("c",vec![[1.25;2];cells]).on_cells()});
        }
    }
    let mut b=a.clone();
    b.point_data[0].data=FieldData::Scalar(vec![1.75;points].into());
    if mode!="fixed" {b.positions=a.positions.iter().map(|p|[p[0],p[1],p[2]+0.25]).collect::<Vec<_>>().into();}
    if mode=="dense" {
        for field in &mut b.point_data[1..] {
            field.data=match field.data {FieldData::Vector(_)=>FieldData::Vector(vec![[1.75;3];points].into()),FieldData::Tensor(_)=>FieldData::Tensor(vec![[1.75;6];points].into()),FieldData::Complex(_)=>FieldData::Complex(vec![[1.75;2];points].into()),_=>unreachable!()};
        }
        for field in &mut b.cell_data {
            field.data=match field.data {FieldData::Scalar(_)=>FieldData::Scalar(vec![1.75;cells].into()),FieldData::Vector(_)=>FieldData::Vector(vec![[1.75;3];cells].into()),FieldData::Tensor(_)=>FieldData::Tensor(vec![[1.75;6];cells].into()),FieldData::Complex(_)=>FieldData::Complex(vec![[1.75;2];cells].into())};
        }
    }
    TimeSeries::new(vec![a,b],vec![0.0,1.0]).unwrap()
}

fn check(output:&DataSet,mode:&str) {
    output.validate().unwrap();
    assert_eq!(output.positions[0],[0.0,0.0,if mode=="fixed" {0.0} else {0.125}]);
    for field in &output.point_data {
        let expected=if field.name.as_ref()=="p" || mode=="dense" {1.5} else {1.25};
        match &field.data {
            FieldData::Scalar(v)=>assert!(v.iter().all(|x|*x==expected)),
            FieldData::Vector(v)=>assert!(v.iter().flatten().all(|x|*x==expected)),
            FieldData::Tensor(v)=>assert!(v.iter().flatten().all(|x|*x==expected)),
            FieldData::Complex(v)=>assert!(v.iter().flatten().all(|x|*x==expected)),
        }
    }
    for field in &output.cell_data {
        let expected=if mode=="dense" {1.5} else {1.25};
        match &field.data {FieldData::Scalar(v)=>assert!(v.iter().all(|x|*x==expected)),FieldData::Vector(v)=>assert!(v.iter().flatten().all(|x|*x==expected)),FieldData::Tensor(v)=>assert!(v.iter().flatten().all(|x|*x==expected)),FieldData::Complex(v)=>assert!(v.iter().flatten().all(|x|*x==expected))}
    }
    assert!(output.field(Association::Point,"p").is_some());
}

fn measure(n:usize,mode:&str,case:&str,operation:impl Fn()->DataSet) {
    let warm=black_box(operation());check(&warm,mode);drop(warm);
    let mut times=Vec::with_capacity(5);let mut calls=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let mut probe=AllocProbe::new();let start=Instant::now();let output=black_box(operation());let elapsed=start.elapsed().as_nanos();let sample=probe.sample("time");
        times.push(elapsed);calls.push(sample.count);bytes.push(sample.bytes);check(&output,mode);drop(output);
    }
    println!(r#"{{"n":{n},"mode":"{mode}","case":"{case}","times_ns":{times:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

#[cfg(feature="retained")]
fn measure_prepare(n:usize,mode:&str,series:&TimeSeries) {
    let warm=black_box(series.clone().prepare().unwrap());check(&warm.sample(0.5).unwrap(),mode);drop(warm);
    let mut times=Vec::with_capacity(5);let mut calls=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let input=series.clone(); // ownership input assembled outside the measurement
        let mut probe=AllocProbe::new();let start=Instant::now();let prepared=black_box(input.prepare().unwrap());let elapsed=start.elapsed().as_nanos();let sample=probe.sample("prepare-time");
        times.push(elapsed);calls.push(sample.count);bytes.push(sample.bytes);check(&prepared.sample(0.5).unwrap(),mode);drop(prepared);
    }
    println!(r#"{{"n":{n},"mode":"{mode}","case":"prepare","times_ns":{times:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

fn main() {
    for n in [16usize,32,48] {for mode in ["fixed","deformed","dense"] {
        let series=fixture(n,mode,false);
        measure(n,mode,"cold_sample",||series.sample(0.5).unwrap());
        #[cfg(feature="retained")]
        {measure_prepare(n,mode,&series);let prepared=series.clone().prepare().unwrap();measure(n,mode,"retained_sample",||prepared.sample(0.5).unwrap());}
        let simple=fixture(n,mode,true);
        #[cfg(feature="retained")]
        let mut player=Player::new(simple).unwrap();
        #[cfg(not(feature="retained"))]
        let mut player=Player::new(simple);
        #[cfg(feature="retained")]
        player.seek(0.5).unwrap();
        #[cfg(not(feature="retained"))]
        player.seek(0.5);
        #[cfg(feature="retained")]
        measure(n,mode,"player_current",||player.current().unwrap());
        #[cfg(not(feature="retained"))]
        measure(n,mode,"player_current",||player.current());
    }}
}
